import java.util.*

fun main() {
    val t = 1
    repeat(t) {
        val parts = readLine()!!.split(" ")
        val n = parts[0].toLong()
        val m = parts[1].toLong()
        val k = parts[2].toLong()
        val a = LongArray(n)
        for (i in 0 until n) {
            a[i] = readLine()!!.trim().toLong()
        }
        a.sort()
        if (m <= k) {
            println(0)
        } else {
            var sum = 0L
            var i = n
            var devices = m
            var soc = k
            while (sum < m && devices > soc && i >= 1) {
                i--
                sum += a[i]
                devices -= a[i]
                soc--
            }
            if (devices <= soc) {
                println(n - i)
            } else {
                var idx = n
                var used = 0L
                var ss = 0L
                var j = 0L
                while (idx >= 1 && ss < m) {
                    idx--
                    if (used >= k * j && j >= 1) {
                        ss--
                    }
                    ss += a[idx]
                    used++
                    if (used % k == 0L && used != 0L) {
                        j++
                    }
                }
                if (ss >= m) {
                    println(used)
                } else {
                    println(-1)
                }
            }
        }
    }
}
